begin;
with j as (select * from jsonb_to_recordset($law7d0040$[{"code_id":"KoAP_RF","article_number":"2.6","version_date":"2001-12-30","article_text":"1. Иностранные граждане, лица без гражданства и иностранные юридические лица, совершившие на территории Российской Федерации административные правонарушения, подлежат административной ответственности на общих основаниях.","article_title":"Статья 2.6. Административная ответственность иностранных граждан, лиц без гражданства и иностранных юридических лиц","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e78a39e3145d9ff061ed48f97988eafe32890c102bb4d52cb030c4942e88fd7b"},{"code_id":"KoAP_RF","article_number":"2.61","version_date":"2001-12-30","article_text":"(Дополнение статьей - Федеральный закон от 24.07.2007 № 210-ФЗ)","article_title":"Статья 2.61. Административная ответственность собственников (владельцев) транспортных средств","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"361d8aec23b5363d42ca9a3047f0900c6bcaa6bcadd71d6105b2bb1eeb5d0a95"},{"code_id":"KoAP_RF","article_number":"2.62","version_date":"2001-12-30","article_text":"1. К административной ответственности за административные правонарушения в области благоустройства территории, предусмотренные законами субъектов Российской Федерации, в части содержания, эксплуатации, перемещения, переоборудования либо разрушения объектов благоустройства в случае фиксации этих административных правонарушений работающими в автоматическом режиме специальными техническими средствами, имеющими функции фото- и киносъемки, видеозаписи, или средствами фото- и киносъемки, видеозаписи привлекаются собственники или иные владельцы земельных участков либо других объектов недвижимости.\n\n2. Собственник или иной владелец земельного участка либо другого объекта недвижимости освобождается от административной ответственности, если в ходе рассмотрения жалобы на постановление по делу об административном правонарушении, вынесенное в соответствии с частью 3 статьи 28.6 настоящего Кодекса, будут подтверждены содержащиеся в ней данные о том, что в момент фиксации административного правонарушения земельный участок либо другой объект недвижимости находился во владении или в пользовании другого лица, либо о том, что административное правонарушение совершено в результате противоправных действий других лиц, при этом у собственника или иного владельца земельного участка либо другого объекта недвижимости не имелось возможности предотвратить совершение административного правонарушения либо им были приняты все зависящие от него меры для предотвращения совершения административного правонарушения.\n\n(Дополнение статьей - Федеральный закон от 28.07.2012 № 133-ФЗ)","article_title":"Статья 2.62. Административная ответственность собственников или иных владельцев земельных участков либо других объектов недвижимости","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d6e8841fdfcf4f384e66f4394c1a3488058925debb841933943000c2703deb2d"},{"code_id":"KoAP_RF","article_number":"2.7","version_date":"2001-12-30","article_text":"Не является административным правонарушением причинение лицом вреда охраняемым законом интересам в состоянии крайней необходимости, то есть для устранения опасности, непосредственно угрожающей личности и правам данного лица или других лиц, а также охраняемым законом интересам общества или государства, если эта опасность не могла быть устранена иными средствами и если причиненный вред является менее значительным, чем предотвращенный вред.","article_title":"Статья 2.7. Крайняя необходимость","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a2e9ed0cdcb0bc5b8f6142273fb6af4bd0fe0e60dfd54c1d26a6bcb1a3c5a684"},{"code_id":"KoAP_RF","article_number":"2.8","version_date":"2001-12-30","article_text":"Не подлежит административной ответственности физическое лицо, которое во время совершения противоправных действий (бездействия) находилось в состоянии невменяемости, то есть не могло осознавать фактический характер и противоправность своих действий (бездействия) либо руководить ими вследствие хронического психического расстройства, временного психического расстройства, слабоумия или иного болезненного состояния психики.","article_title":"Статья 2.8. Невменяемость","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fa836176a84f3f82b9dfb69261c1f10c641497653ff541f93607a2486033d995"},{"code_id":"KoAP_RF","article_number":"2.9","version_date":"2001-12-30","article_text":"При малозначительности совершенного административного правонарушения судья, орган, должностное лицо, уполномоченные решить дело об административном правонарушении, могут освободить лицо, совершившее административное правонарушение, от административной ответственности и ограничиться устным замечанием.","article_title":"Статья 2.9. Возможность освобождения от административной ответственности при малозначительности административного правонарушения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6dfbfe4c987de4b74cb7b7cf4b4806c5edbeaf0fc630bc01be427cf7a33f36f0"},{"code_id":"KoAP_RF","article_number":"3.1","version_date":"2001-12-30","article_text":"1. Административное наказание является установленной государством мерой ответственности за совершение административного правонарушения и применяется в целях предупреждения совершения новых правонарушений как самим правонарушителем, так и другими лицами.\n\n2. Административное наказание не может иметь своей целью унижение человеческого достоинства физического лица, совершившего административное правонарушение, или причинение ему физических страданий, а также нанесение вреда деловой репутации юридического лица.","article_title":"Статья 3.1. Цели административного наказания","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d4f8a0b5e65e37714a61ae54fd229f1b1f6b2ec0d2e44cf1e433d77f52a4421d"},{"code_id":"KoAP_RF","article_number":"3.11","version_date":"2001-12-30","article_text":"(Статья в редакции Федерального закона от 17.07.2009 № 160-ФЗ)","article_title":"Статья 3.11. Дисквалификация","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c53706c9a92ac4fc927284a04f982e16275628714d3e7ed81c0598ba7a64913d"},{"code_id":"KoAP_RF","article_number":"3.12","version_date":"2001-12-30","article_text":"1. Административное приостановление деятельности заключается во временном прекращении деятельности лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, юридических лиц, их филиалов, представительств, структурных подразделений, производственных участков, а также эксплуатации агрегатов, объектов, зданий или сооружений, осуществления отдельных видов деятельности (работ), оказания услуг. Административное приостановление деятельности применяется в случае угрозы жизни или здоровью людей, возникновения эпидемии, эпизоотии, заражения (засорения) подкарантинных объектов карантинными объектами, наступления радиационной аварии или техногенной катастрофы, причинения существенного вреда состоянию или качеству окружающей среды либо в случае совершения административного правонарушения в области оборота наркотических средств, психотропных веществ и их прекурсоров, растений, содержащих наркотические средства или психотропные вещества либо их прекурсоры, и их частей, содержащих наркотические средства или психотропные вещества либо их прекурсоры, в области противодействия легализации (отмыванию) доходов, полученных преступным путем, финансированию терроризма, экстремистской деятельности и финансированию распространения оружия массового уничтожения, в области инвестиционной деятельности (в части административных правонарушений, предусмотренных статьей 14.561 настоящего Кодекса), в области установленных в соответствии с федеральным законом в отношении иностранных граждан, лиц без гражданства и иностранных организаций ограничений на осуществление отдельных видов деятельности, в области правил привлечения иностранных граждан и лиц без гражданства к трудовой деятельности, в области п\n\nорядка управления, в области общественного порядка и общественной безопасности, в области производства и оборота этилового спирта, алкогольной и спиртосодержащей продукции, в области производства и оборота табачных изделий, табачной продукции, никотинсодержащей продукции и сырья для производства такой продукции, в области градостроительной деятельности, в области транспортной безопасности, в области охраны собственности, в области деятельности по предоставлению потребительских кредитов (займов), в том числе обязательства заемщика по которым обеспечены ипотекой, в области применения контрольно-кассовой техники, в области реализации входных билетов на матчи чемпионата Европы по футболу UEFA 2020 года или документов, дающих право на получение входных билетов на матчи чемпионата Европы по футболу UEFA 2020 года, а также в случае совершения административного правонарушения, посягающего на здоровье, санитарно-эпидемиологическое благополучие населения и общественную нравственность. (В редакции  федеральных законов от 05.11.2006 № 189-ФЗ, от 18.12.2006 № 232-ФЗ, от 24.07.2007 № 211-ФЗ, от 19.05.2010 № 87-ФЗ, от 27.07.2010 № 195-ФЗ, от 29.12.2012 № 277-ФЗ, от 05.04.2013 № 58-ФЗ, от 21.10.2013 № 275-ФЗ, от 21.12.2013 № 365-ФЗ, от 21.07.2014 № 210-ФЗ, от 03.07.2016 № 231-ФЗ, от 03.07.2016 № 290-ФЗ, от 05.02.2018 № 13-ФЗ, от 01.05.2019 № 95-ФЗ, от 26.07.2019 № 218-ФЗ, от 11.06.2021 № 203-ФЗ, от 10.07.2023 № 322-ФЗ, от 04.08.2023 № 423-ФЗ, от 13.12.2024 № 461-ФЗ, от 13.12.2024 № 473-ФЗ, от 28.02.2025 № 15-ФЗ)\n\nАдминистративное приостановление деятельности назначается только в случаях, предусмотренных статьями Особенной части настоящего Кодекса, если менее строгий вид административного наказания не сможет обеспечить достижение цели административного наказания. (В редакции Федерального закона от 23.07.2010 № 171-ФЗ)\n\nАдминистративное приостановление деятельности назначается судьей. За административные правонарушения, предусмотренные частью 3 (в части грубого нарушения требований промышленной безопасности) и частью 31 статьи 9.1 настоящего Кодекса, административное приостановление деятельности назначается должностными лицами, указанными в пунктах 1 и 4 части 2 статьи 23.31 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 28.12.2010 № 421-ФЗ) (В редакции  Федерального закона от 25.12.2023 № 638-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 09.05.2005 № 45-ФЗ)","article_title":"Статья 3.12. Административное приостановление деятельности","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3d548dca83a7aa96c527f8eacde79d4b3afeb67571ef76f4c452be0a0231d5fa"},{"code_id":"KoAP_RF","article_number":"3.13","version_date":"2001-12-30","article_text":"1. Обязательные работы заключаются в выполнении физическим лицом, совершившим административное правонарушение, в свободное от основной работы, службы или учебы время бесплатных общественно полезных работ. Обязательные работы назначаются судьей.\n\n(Дополнение статьей - Федеральный закон от 08.06.2012 № 65-ФЗ)","article_title":"Статья 3.13. Обязательные работы","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f747e4b257b1012277fbec6d55554b8d1e50bab02d2c5bc002bfe2c4458d0ae2"},{"code_id":"KoAP_RF","article_number":"3.14","version_date":"2001-12-30","article_text":"1. Административный запрет на посещение мест проведения официальных спортивных соревнований в дни их проведения заключается во временном запрете гражданину на посещение таких мест в дни проведения официальных спортивных соревнований и устанавливается за нарушение правил поведения зрителей при проведении официальных спортивных соревнований. Административный запрет на посещение мест проведения официальных спортивных соревнований в дни их проведения назначается судьей.\n\n2. Административный запрет на посещение мест проведения официальных спортивных соревнований в дни их проведения устанавливается на срок от шести месяцев до семи лет.\n\n(Дополнение статьей - Федеральный закон от 23.07.2013 № 192-ФЗ)\n\nГЛАВА 4. НАЗНАЧЕНИЕ АДМИНИСТРАТИВНОГО НАКАЗАНИЯ","article_title":"Статья 3.14. Административный запрет на посещение мест проведения официальных спортивных соревнований в дни их проведения","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"22726f519d6e754447a94b5c9d2fef4585ad444d7ba95bd90d18efe8833668de"},{"code_id":"KoAP_RF","article_number":"3.2","version_date":"2001-12-30","article_text":"1. За совершение административных правонарушений могут устанавливаться и применяться следующие административные наказания:\n\n1) предупреждение;\n\n2) административный штраф;\n\n3) (Пункт утратил силу - Федеральный закон от 28.12.2010 № 398-ФЗ)\n\n4) конфискация орудия совершения или предмета административного правонарушения;\n\n5) лишение специального права, предоставленного физическому лицу;\n\n6) административный арест;\n\n7) административное выдворение за пределы Российской Федерации иностранного гражданина или лица без гражданства;\n\n8) дисквалификация;\n\n9) административное приостановление деятельности; (Дополнение пунктом - Федеральный закон от 09.05.2005 № 45-ФЗ)\n\n10) обязательные работы; (Дополнение пунктом - Федеральный закон от 08.06.2012 № 65-ФЗ)\n\n11) административный запрет на посещение мест проведения официальных спортивных соревнований в дни их проведения. (Дополнение пунктом - Федеральный закон от 23.07.2013 № 192-ФЗ)","article_title":"Статья 3.2. Виды административных наказаний","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e48e97dec90e07cb5f0043944bd14ede71d1b0748c367fc72827a8d393827ab7"},{"code_id":"KoAP_RF","article_number":"3.4","version_date":"2001-12-30","article_text":"1. Предупреждение - мера административного наказания, выраженная в официальном порицании физического или юридического лица. Предупреждение выносится в письменной форме.\n\n2. Предупреждение устанавливается за впервые совершенные административные правонарушения при отсутствии причинения вреда или возникновения угрозы причинения вреда жизни и здоровью людей, объектам животного и растительного мира, окружающей среде, объектам культурного наследия (памятникам истории и культуры) народов Российской Федерации, безопасности государства, угрозы чрезвычайных ситуаций природного и техногенного характера, а также при отсутствии имущественного ущерба.\n\n(Статья в редакции Федерального закона от 27.07.2010 № 239-ФЗ)","article_title":"Статья 3.4. Предупреждение","amendment_eo_number":"195-ФЗ","amendment_date":"2001-12-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"25219059f5ba7334a34891f8849c48d5f6aac5b540035832a62750b703e1c9ae"},{"code_id":"KoAP_RF","article_number":"3.5","version_date":"2001-12-30","article_text":"1. Административный штраф является денежным взысканием, выражается в рублях и устанавливается для граждан в размере, не превышающем пяти тысяч рублей, а в случаях, предусмотренных частью 2 статьи 6.23, частями 5 и 7 статьи 6.35, частями 3, 5 и 6 статьи 8.2, частью 4 статьи 8.23, частью 2 статьи 19.151, частью 2 статьи 19.152 настоящего Кодекса, - семи тысяч рублей, в случаях, предусмотренных частью 2 статьи 5.61, частями 6, 8 - 10 статьи 6.35, статьями 7.1, 7.2, частью 1 статьи 8.22, ча